(() => {
const $=s=>document.querySelector(s);
let user=null,notes=[],current=null,today=1,view='today',shown=24,dirty=false;
let setup=new URLSearchParams(location.hash.slice(1)).get('setup');
if(setup)history.replaceState(null,'',location.pathname);
async function api(path,options={}){const r=await fetch('/api/'+path,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...options});const data=await r.json();if(!r.ok){if(r.status===401&&user)lock();throw new Error(data.error||'Something went wrong. Please try again.');}return data;}
function lock(){user=null;notes=[];current=null;$('#auth-screen').hidden=false;document.querySelector('main').hidden=true;$('#gift-intro').hidden=true;$('#daily-note').textContent='A little love is waiting for you.';$('#note-list').replaceChildren();$('#edit-text').value='';$('#auth-password').value='';}
function render(){if(!current)return;$('#day-number').textContent=`Day ${current.day} of 365`;$('#daily-note').textContent=current.text;$('#note-date').textContent=current.day===today?$('#note-date').dataset.today:'From your collection';$('#note-kind').textContent=current.day===today?'a little love for today':'whenever you need it';$('#previous').disabled=current.day===1;$('#next').disabled=current.day===365;$('#back-today').hidden=current.day===today;$('#editor').hidden=true;$('#edit-note').hidden=user.role!=='admin';dirty=false;}
function showDay(day){if(dirty&&!confirm('Discard your unsaved changes?'))return;dirty=false;current=notes.find(n=>n.day===day);setView('today',false);render();}
function setView(next,reset=true){if(dirty&&!confirm('Discard your unsaved changes?'))return;dirty=false;view=next;$('#editor').hidden=true;$('#daily-view').hidden=view!=='today';$('#collection-view').hidden=view==='today';document.querySelectorAll('[data-view]').forEach(b=>{if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(view==='today'){if(reset&&user.role==='admin')current=notes.find(n=>n.day===today);render();}else{shown=24;$('#search').value='';collection();}}
function collection(){const query=$('#search').value.toLowerCase().trim(),filtered=notes.filter(n=>n.text.toLowerCase().includes(query)||String(n.day)===query);$('#results-count').textContent=`${filtered.length} notes${query?' found':''}`;$('#note-list').replaceChildren();filtered.slice(0,shown).forEach(n=>{const li=document.createElement('li'),b=document.createElement('button'),day=document.createElement('span'),text=document.createElement('span');day.className='list-day';day.textContent=`Day ${n.day}`;text.textContent=n.text;b.append(day,text);b.onclick=()=>{showDay(n.day);$('#daily-view').scrollIntoView({block:'start'});};li.append(b);$('#note-list').append(li);});$('#load-more').hidden=shown>=filtered.length;}
async function refresh(){const data=await api('today');today=data.note.day;$('#note-date').dataset.today=data.date;if(user.role==='admin'){notes=(await api('notes')).notes;current=notes.find(n=>n.day===today);}else current=data.note;render();}
async function boot(account){user=account;$('#auth-submit').disabled=true;try{await refresh();setView('today',false);$('#auth-screen').hidden=true;$('#logout').hidden=false;$('#admin-label').textContent=user.role==='admin'?'Owner’s note studio':'just for Love';document.querySelector('.love-nav').hidden=user.role!=='admin';document.querySelector('.day-controls').hidden=user.role!=='admin';$('#saved-tab').hidden=true;$('#save-note').hidden=true;$('#auth-password').value='';$('#auth-confirm').value='';window.dispatchEvent(new Event('signed-in'));}catch(e){lock();$('#auth-status').textContent=e.message;}finally{$('#auth-submit').disabled=false;}}
function configure(){const isSetup=!!setup;$('#auth-title').textContent=isSetup?'Your little place awaits.':'A little place for us.';$('#auth-description').textContent=isSetup?'Choose a password for your account. Just for the two of you.':'Sign in for a little love, just for you.';$('#username-row').hidden=isSetup;$('#confirm-row').hidden=!isSetup;$('#auth-name').required=!isSetup;$('#auth-confirm').required=isSetup;$('#auth-password').autocomplete=isSetup?'new-password':'current-password';$('#auth-password').minLength=isSetup?12:1;$('#auth-submit').textContent=isSetup?'Set password & come in ♡':'Come on in ♡';$('#password-hint').hidden=!isSetup;}
$('#auth-form').onsubmit=async e=>{e.preventDefault();$('#auth-status').textContent='';if(setup&&$('#auth-password').value!==$('#auth-confirm').value){$('#auth-status').textContent='Those passwords don’t match yet.';return;}$('#auth-submit').disabled=true;try{const result=await api(setup?'setup':'login',{method:'POST',body:JSON.stringify(setup?{token:setup,password:$('#auth-password').value}:{name:$('#auth-name').value,password:$('#auth-password').value})});setup=null;configure();await boot(result.user);}catch(error){$('#auth-status').textContent=error.message;}finally{$('#auth-submit').disabled=false;}};
$('#logout').onclick=async()=>{try{await api('logout',{method:'POST',body:'{}'});lock();configure();$('#auth-status').textContent='You’re signed out. Your little notes will be here.';}catch(e){$('#storage-status').textContent=e.message;}};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#previous').onclick=()=>showDay(current.day-1);$('#next').onclick=()=>showDay(current.day+1);$('#back-today').onclick=()=>showDay(today);$('#search').oninput=()=>{shown=24;collection();};$('#load-more').onclick=()=>{shown+=24;collection();};
$('#edit-note').onclick=()=>{$('#editor').hidden=false;$('#edit-text').value=current.text;$('#edit-status').textContent='';$('#edit-text').focus();};$('#edit-text').oninput=()=>{dirty=true;};$('#cancel-edit').onclick=()=>{if(!dirty||confirm('Discard your unsaved changes?')){$('#editor').hidden=true;dirty=false;}};
$('#edit-form').onsubmit=async e=>{e.preventDefault();$('#edit-save').disabled=true;$('#edit-status').textContent='Saving…';try{const result=await api('notes/'+current.day,{method:'PUT',body:JSON.stringify({text:$('#edit-text').value,revision:current.revision})});current=result.note;notes=notes.map(n=>n.day===current.day?current:n);render();$('#storage-status').textContent=`Day ${current.day} saved on your server.`;}catch(error){$('#edit-status').textContent=error.message;}finally{$('#edit-save').disabled=false;}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
const lines=['prrrr. you are very, very loved.','your note has been inspected. and sat on.','tiny paws. big love.'];let pets=0;$('#cat').onclick=()=>{$('#cat-message').textContent=lines[pets++%lines.length];};$('#show-heart').onclick=()=>window.dispatchEvent(new Event('show-love'));
let lastCheck=Date.now();setInterval(async()=>{if(!user||document.hidden||dirty||Date.now()-lastCheck<60000)return;lastCheck=Date.now();try{const data=await api('today');if(today!==data.note.day){today=data.note.day;$('#note-date').dataset.today=data.date;if(user.role==='reader'){current=data.note;render();}else await refresh();}}catch(e){$('#storage-status').textContent=e.message;}},60000);
document.addEventListener('DOMContentLoaded',async()=>{configure();if(setup)return;try{const data=await api('me');if(data.user)await boot(data.user);}catch(e){$('#auth-status').textContent='Can’t reach your little place right now. Please try again.';}});
})();
